def main():
    global NEET_TOPICS, MRCP_TOPICS, FCPS_TOPICS
    NEET_TOPICS = (NEET_TOPICS + NEET_ADDITIONAL)[:100]
    MRCP_TOPICS = MRCP_TOPICS[:100]
    FCPS_TOPICS = FCPS_TOPICS[:100]

    print(f"Total NEET topics: {len(NEET_TOPICS)}")
    print(f"Total MRCP topics: {len(MRCP_TOPICS)}")
    print(f"Total FCPS topics: {len(FCPS_TOPICS)}")

    assert len(NEET_TOPICS) == 100, f"Expected 100 NEET topics, got {len(NEET_TOPICS)}"
    assert len(MRCP_TOPICS) == 100, f"Expected 100 MRCP topics, got {len(MRCP_TOPICS)}"
    assert len(FCPS_TOPICS) == 100, f"Expected 100 FCPS topics, got {len(FCPS_TOPICS)}"

    for title, subj, sys_name, snip, g_name, g_url in NEET_TOPICS:
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {title}"
        assert g_url.startswith("https://"), f"Invalid url {g_url} in {title}"
        assert len(snip) > 20

    for title, subj, sys_name, snip, g_name, g_url in MRCP_TOPICS:
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {title}"
        assert g_url.startswith("https://"), f"Invalid url {g_url} in {title}"
        assert len(snip) > 20

    for title, subj, sys_name, snip, g_name, g_url in FCPS_TOPICS:
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {title}"
        assert g_url.startswith("https://"), f"Invalid url {g_url} in {title}"
        assert len(snip) > 20

    out_path = os.path.join(os.path.dirname(__file__), "mega42_topics_b.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 42 Topics Part B\n")
        f.write("# NEET PG (100 topics) + MRCP (100 topics) + FCPS (100 topics)\n\n")
        f.write(f"NEET_TOPICS = {repr(NEET_TOPICS)}\n\n")
        f.write(f"MRCP_TOPICS = {repr(MRCP_TOPICS)}\n\n")
        f.write(f"FCPS_TOPICS = {repr(FCPS_TOPICS)}\n")
    print(f"Successfully generated {out_path}!")

if __name__ == "__main__":
    main()
